#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>
#define N 413
#define HSIZE 1024
static const char *names[N] = {
'''+arr+r'''
};
static uint32_t hval[HSIZE];
static int hid[HSIZE];
static uint32_t hashname(const char *s, int n) {
  uint32_t h=5381; for(int i=0;i<n;i++) h=((h<<5)+h) ^ (unsigned char)s[i]; return h;
}
typedef struct { const char *a,*b; int mn[N],mx[N]; long long sum[N]; int cnt[N]; } Job;
static void *work(void *arg) {
 Job *j=arg; for(int i=0;i<N;i++) {j->mn[i]=10000;j->mx[i]=-10000;}
 const char *p=j->a, *e=j->b;
 while(p<e) {
   const char *s=p; uint32_t h=5381; char c;
   do { c=*p++; h=((h<<5)+h)^(unsigned char)c; } while(c!=';');
   int n=(int)(p-s-1), slot=h&(HSIZE-1);
   while(hval[slot]!=h || strncmp(names[hid[slot]],s,n) || names[hid[slot]][n]) slot=(slot+1)&(HSIZE-1);
   int id=hid[slot]; int neg=0; if(*p=='-'){neg=1;p++;}
   int x=(unsigned)(*p++-'0'); if(*p!='.') x=x*10+(*p++-'0');
   p++; x=x*10+(*p++-'0'); if(neg)x=-x;
   while(*p++!='\n') {}
   if(x<j->mn[id])j->mn[id]=x; if(x>j->mx[id])j->mx[id]=x; j->sum[id]+=x; j->cnt[id]++;
 }
 return NULL;
}
static void put10(long long x) { if(x<0) {putchar('-');x=-x;} printf("%lld.%lld",x/10,x%10); }
int main(int ac,char **av) {
 if(ac!=2)return 2; int fd=open(av[1],O_RDONLY); if(fd<0)return 2; struct stat st; fstat(fd,&st); size_t z=st.st_size;
 const char *d=mmap(0,z,PROT_READ,MAP_PRIVATE,fd,0); if(d==MAP_FAILED)return 2;
 for(int i=0;i<HSIZE;i++) hval[i]=0xffffffff;
 for(int i=0;i<N;i++){uint32_t h=hashname(names[i],strlen(names[i]));int q=h&(HSIZE-1);while(hval[q]!=0xffffffff)q=(q+1)&(HSIZE-1);hval[q]=h;hid[q]=i;}
 int nt=6; const char *cuts[7]; cuts[0]=d; cuts[nt]=d+z;
 for(int i=1;i<nt;i++){const char *q=d+z*i/nt;while(*q++!='\n');cuts[i]=q;}
 Job jobs[6]; pthread_t th[6]; for(int i=0;i<nt;i++){jobs[i]=(Job){.a=cuts[i],.b=cuts[i+1]};pthread_create(th+i,0,work,jobs+i);}
 int mn[N],mx[N];long long su[N];int co[N]; for(int k=0;k<N;k++){mn[k]=10000;mx[k]=-10000;su[k]=0;co[k]=0;}
 for(int i=0;i<nt;i++){pthread_join(th[i],0);for(int k=0;k<N;k++){if(jobs[i].mn[k]<mn[k])mn[k]=jobs[i].mn[k];if(jobs[i].mx[k]>mx[k])mx[k]=jobs[i].mx[k];su[k]+=jobs[i].sum[k];co[k]+=jobs[i].cnt[k];}}
 putchar('{'); for(int k=0;k<N;k++){if(k)fputs(", ",stdout);fputs(names[k],stdout);putchar('=');put10(mn[k]);putchar('/');long long a=su[k]<0?-su[k]:su[k], r=(2*a+co[k])/(2LL*co[k]);if(su[k]<0)r=-r;put10(r);putchar('/');put10(mx[k]);}putchar('}');
 return 0;
}
''')
